import{_ as o,C as r,o as a,c as n,ag as s,E as d}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Glossary","description":"Common terms used across the Takoform documentation and specification","frontmatter":{"page_title":"Takoform glossary","description":"Common terms used across the Takoform documentation and specification"},"headers":[],"relativePath":"docs/glossary.md","filePath":"docs/glossary.md"}'),i={name:"docs/glossary.md"};function c(l,e,m,p,g,h){const t=r("StatusNote");return a(),n("div",null,[e[0]||(e[0]=s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>These definitions summarize the current vocabulary. Normative meaning lives in the <a href="/docs/">current Host API and Form/Core contracts</a>.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Form</strong></td><td>One portable desired-state contract: a named, versioned definition of what a workload needs from any host.</td></tr><tr><td><strong>FormRef</strong></td><td>The exact immutable identity of a Form: versionless reverse-DNS family group, <code>kind</code>, definition version, and schema digest. Compatibility is never inferred from a name alone.</td></tr><tr><td><strong>Form Definition</strong></td><td>Deterministic, data-only JSON describing one Form: desired/observed/output schemas, immutable fields, lifecycle capabilities, and interface descriptors (<a href="/spec/form-definition/">contract</a>).</td></tr><tr><td><strong>Form Package</strong></td><td>A closed, data-only distribution of one Form Definition plus fixtures, bound by a canonical content digest (<a href="/spec/form-package/">contract</a>). It is a distribution envelope, not a product release axis; no executable or credential content is allowed.</td></tr><tr><td><strong>schemaDigest</strong></td><td>SHA-256 over the RFC 8785 canonical Form Definition bytes.</td></tr><tr><td><strong>packageDigest</strong></td><td>SHA-256 over the RFC 8785 canonical package index; it locates one package (<code>sha256-&lt;hex&gt;</code>).</td></tr><tr><td><strong>Form Family</strong></td><td>A versionless namespaced Form group, such as <code>edge.forms.takoform.com</code>, whose members share exact Interface and Binding contracts. The current official corpus is one Edge family with 16 Experimental <code>0.x</code> FormRefs.</td></tr><tr><td><strong>Resource Role</strong></td><td>Closed role enum — <code>identity</code>, <code>revision</code>, <code>deployment</code>, <code>attachment</code>, <code>policy</code> — deciding one Form&#39;s lifecycle mechanics.</td></tr><tr><td><strong>Envelope</strong></td><td>The package API version used to carry a Form. Current publisher data uses <code>packages.forms.takoform.com/v1alpha5</code>; this is a wire/envelope format, not another product version stream. Retained older envelopes remain immutable history.</td></tr><tr><td><strong>Space</strong></td><td>Opaque, case-sensitive scope identity (<code>SpaceID</code>) that scopes Resources, Interface reads, idempotency, and Provider configuration.</td></tr><tr><td><strong>Host</strong></td><td>Any implementation of the Host API that advertises exact FormRefs, executes the portable lifecycle, and owns placement, credentials, and recovery.</td></tr><tr><td><strong>Host API</strong></td><td>Versioned HTTP contract (<a href="/spec/host-api/">Host API</a>) for discovery, exact Form availability, preview/apply, read/import/observe/delete, fencing, and stable errors. The current stable wire is <code>forms.takoform.com/v1</code>.</td></tr><tr><td><strong>Discovery</strong></td><td>Versioned well-known endpoint at which a host advertises its API, Forms, and features: <code>/.well-known/takoform/v1</code> for the current Host API.</td></tr><tr><td><strong>Provider</strong></td><td>Terraform/OpenTofu software tooling with typed mappings for the official Forms it explicitly supports. The canonical <code>tako0614/takoform</code> Provider is official-Forms-only, not a generic carrier or universal infrastructure provider. Third-party packages use the same Host API path and package/verification contracts under their own namespaces. Modules may combine the official Takoform Provider with other Takoform or industry-standard Providers.</td></tr><tr><td><strong>Official Form</strong></td><td>A Form distributed by the official publisher and represented in the canonical Provider&#39;s explicit mappings. Independent third parties may distribute Forms under their own namespaces through the same package and verification path.</td></tr><tr><td><strong>Specification receipt</strong></td><td>Numbered archive evidence (including Specification 1.0/1.1). A receipt records history; it does not create an API v1.1 route, a Form <code>1.0.0</code>, or a current Provider lane.</td></tr><tr><td><strong>Interface contract</strong></td><td>One exact named capability contract a Form&#39;s service exposes, such as <code>edge.kv@1.0.0</code> (<a href="/spec/interface-contract/">contracts</a>). Different semantics are a different contract.</td></tr><tr><td><strong>Binding contract</strong></td><td>Typed contract behind one outward capability binding a revision holds, such as <code>module-worker.edge-kv@1.0.0</code> (<a href="/spec/binding-contract/">contracts</a>). Inward activation (routes, domains, cron, consumption) is an attachment, never a binding.</td></tr><tr><td><strong>Standard service</strong></td><td>A sealed Host-resolved runtime slot identified by opaque <code>standards.takoform.com/v1</code> plus a reverse-DNS protocol string. Takoform has no central protocol enum and the slot grants no portable lifecycle over a service Resource.</td></tr><tr><td><strong>artifact manifest</strong></td><td>Content-addressed manifest (<code>artifacts.takoform.com/v1alpha1</code>) committing a bundle&#39;s modules by exact size and sha256 digest through the <a href="/spec/artifact-transport/">artifact transport</a> API.</td></tr><tr><td><strong>uid / generation / revision</strong></td><td>Host API v1 resource identity triple: <code>uid</code> is immutable host identity; <code>generation</code> increments only when portable desired spec changes and fences updates; <code>revision</code> increments on any representation change and fences deletes.</td></tr><tr><td><strong>Proposal</strong></td><td>Mutable, unversioned design material for a Form that has not earned a public FormRef. Non-Edge candidate proposals are currently historical/deferred.</td></tr><tr><td><strong>Experimental</strong></td><td>Reproducible public Form on a <code>0.x</code> line whose semantics may still change under the documented compatibility policy.</td></tr><tr><td><strong>Stable</strong></td><td>Evidence-earned Form contract with independent implementations, interoperability, and operational experience.</td></tr><tr><td><strong>Legacy</strong></td><td>Lifecycle state after the current line is no longer recommended for new work. Historical bytes stay in repository history.</td></tr><tr><td><strong>resource_version</strong></td><td>Withdrawn v2 lane&#39;s canonical positive-decimal desired-state version; on Host API v1 the <code>ETag</code> is the quoted <code>revision</code> and <code>generation</code> remains the mutation fence.</td></tr><tr><td><strong>Idempotency-Key</strong></td><td>Deterministic client-supplied key scoping mutation replay; a retry must reuse the same key and request bytes.</td></tr><tr><td><strong>Checkpoint</strong></td><td>Cumulative, hash-chained revocation checkpoint carrying every statement from sequence 1 through the current sequence.</td></tr><tr><td><strong>Drift</strong></td><td>Lifecycle outcome derived from validated observed evidence; it is not a separate host operation.</td></tr></tbody></table>',3)),d(t)])}const v=o(i,[["render",c]]);export{u as __pageData,v as default};
